@Retention(RUNTIME) @Inherited @Target(TYPE)
public @interface Tag   { String value(); }

@Retention(RUNTIME)            @Target(TYPE)
public @interface Plain { String value(); }   // @Inherited 없음

@Tag("기반") @Plain("평범")
public class Base { }
public class Child extends Base { }           // 아무것도 안 붙였다

@Retention(RUNTIME) @Repeatable(Roles.List.class) @Target(METHOD)
public @interface Roles {
    String value();
    @Retention(RUNTIME) @Target(METHOD)
    @interface List { Roles[] value(); }      // 담는 그릇
}

@Roles("ADMIN") @Roles("USER") public void both() {}
@Roles("GUEST")                public void one()  {}

